changeSet.sql:
ALTER TABLE feedback DROP CONSTRAINT ck_feedback_stop_reason;
ALTER TABLE feedback_copy DROP CONSTRAINT ck_feedback_copy_stop_reason;
UPDATE feedback SET stop_reason='ITEM_NOT_VISIBLE' WHERE stop_reason='APPROVAL_NO_LONGER_ELIGIBLE';
UPDATE feedback_copy SET stop_reason='ITEM_NOT_VISIBLE' WHERE stop_reason='APPROVAL_NO_LONGER_ELIGIBLE';
ALTER TABLE feedback ADD CONSTRAINT ck_feedback_stop_reason CHECK (stop_reason IS NULL OR stop_reason IN ('VOLUME_CAPPED','COMPOSER_WITHHELD','NOTHING_NEW','REPEATS_DELIVERED_NOTE','REACTED_DISAGREE','REACTED_NOT_APPLICABLE','CONVERSATION_EXPIRED','DELIVERY_UNCONFIRMED','ITEM_GONE','ITEM_NOT_VISIBLE','CONSENT_WITHHELD','ITEM_CLOSED','ITEM_MERGED','ITEM_STATE_INELIGIBLE','ISSUE_SNAPSHOT_CHANGED','PUBLIC_SUBJECT_INELIGIBLE','NO_AI','DELIVERY_OFF','PERSON_SUPPRESSED','RECIPIENT_UNAVAILABLE','EMPTY_AFTER_SANITIZE','INSTANCE_SILENCED','FEEDBACK_OFF','WORKSPACE_DISABLED','WORKSPACE_DELIVERY_PAUSED','STALE_ROLLOUT_REVISION','OUTSIDE_CURRENT_SCOPE','APPROVAL_STALE','PRACTICE_REQUIRES_APPROVAL','BACKFILL_QUIET','RESULT_MARKED_INCORRECT','REVIEWED_VERSION_CHANGED','REVIEW_CANCELLED','EVIDENCE_NOT_PERMITTED','NO_EVIDENCE','UNCORROBORATED','PUBLIC_HISTORY_CHANGED','PUBLIC_DELIVERY_UNRESOLVED','STEP_LIMIT','NOT_COMPOSED'));
ALTER TABLE feedback_copy ADD CONSTRAINT ck_feedback_copy_stop_reason CHECK (stop_reason IS NULL OR stop_reason IN ('VOLUME_CAPPED','COMPOSER_WITHHELD','NOTHING_NEW','REPEATS_DELIVERED_NOTE','REACTED_DISAGREE','REACTED_NOT_APPLICABLE','CONVERSATION_EXPIRED','DELIVERY_UNCONFIRMED','ITEM_GONE','ITEM_NOT_VISIBLE','CONSENT_WITHHELD','ITEM_CLOSED','ITEM_MERGED','ITEM_STATE_INELIGIBLE','ISSUE_SNAPSHOT_CHANGED','PUBLIC_SUBJECT_INELIGIBLE','NO_AI','DELIVERY_OFF','PERSON_SUPPRESSED','RECIPIENT_UNAVAILABLE','EMPTY_AFTER_SANITIZE','INSTANCE_SILENCED','FEEDBACK_OFF','WORKSPACE_DISABLED','WORKSPACE_DELIVERY_PAUSED','STALE_ROLLOUT_REVISION','OUTSIDE_CURRENT_SCOPE','APPROVAL_STALE','PRACTICE_REQUIRES_APPROVAL','BACKFILL_QUIET','RESULT_MARKED_INCORRECT','REVIEWED_VERSION_CHANGED','REVIEW_CANCELLED','EVIDENCE_NOT_PERMITTED','NO_EVIDENCE','UNCORROBORATED','PUBLIC_HISTORY_CHANGED','PUBLIC_DELIVERY_UNRESOLVED','STEP_LIMIT','NOT_COMPOSED'));

rollback.sql:
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM feedback WHERE stop_reason IN ('ITEM_NOT_VISIBLE','CONSENT_WITHHELD'))
        OR EXISTS (SELECT 1 FROM feedback_copy WHERE stop_reason IN ('ITEM_NOT_VISIBLE','CONSENT_WITHHELD')) THEN
        RAISE EXCEPTION 'Cannot remove stop reasons used by existing feedback. Restore a verified backup instead.';
    END IF;
END $$;
ALTER TABLE feedback DROP CONSTRAINT ck_feedback_stop_reason;
ALTER TABLE feedback_copy DROP CONSTRAINT ck_feedback_copy_stop_reason;
